@Transactional
public void update(long id, String email) {
    Author a = em.find(Author.class, id);
    a.setEmail(email);            // staged, no SQL yet
    a.setLastSeen(Instant.now()); // coalesced with the previous change
    // single flush at commit; em.flush() forces it before a query that
    // must observe the pending write
}

